package com.company.platform.order.infrastructure;
import com.company.platform.order.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class JdbcOrderItemRepository implements OrderItemRepository{private final JdbcTemplate jdbc;public JdbcOrderItemRepository(JdbcTemplate j){jdbc=j;}private OrderItem map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new OrderItem((UUID)r.getObject("id"),(UUID)r.getObject("order_id"),(UUID)r.getObject("sellable_product_id"),r.getString("product_snapshot"),r.getInt("quantity"),new Money(r.getBigDecimal("unit_price"),Currency.getInstance(r.getString("currency"))),new Money(r.getBigDecimal("subtotal"),Currency.getInstance(r.getString("currency"))));}public List<OrderItem> findByTenantIdAndOrderId(UUID t,UUID o){return jdbc.query("SELECT * FROM order_items WHERE tenant_id=? AND order_id=? ORDER BY created_at",this::map,t,o);}}
